const RANK = { error: 0, info: 1, debug: 2 };
/** Logs go to stderr so that stdout carries only the script result. */
export class Logger {
    level;
    sink;
    constructor(level = 'info', sink = (l) => process.stderr.write(l + '\n')) {
        this.level = level;
        this.sink = sink;
    }
    emit(min, tag, msg) {
        if (this.level === 'silent' || RANK[this.level] < RANK[min])
            return;
        this.sink(`[${tag}] ${msg}`);
    }
    error(msg) {
        this.emit('error', 'error', msg);
    }
    warn(msg) {
        this.emit('info', 'warn', msg);
    }
    info(msg) {
        this.emit('info', 'info', msg);
    }
    debug(msg) {
        this.emit('debug', 'debug', msg);
    }
}
